def final_compositions(rows, region):
    result=[]
    for entry in rows:
        entry=list(entry)
        short=entry[0]
        key=('tidekin_sea_'+short) if region=='tidekin_sea' else ('open_lands_'+short if short.startswith(('path_','site_','return_')) else short)
        entry[2]=COMPOSITIONS[key]
        result.append(tuple(entry))
    return result
